import React from 'react';
import ReactDOM from 'react-dom';
import { Nav } from '@alifd/next';

const { Item, SubNav } = Nav;

function App() {
  return (
    <div style={{ width: 80, border: '1px solid #ddd' }}>
      {/* 开启 iconOnly，只显示图标 */}
      <Nav
        direction="ver"
        iconOnly={true}
        hasArrow={true}
        hasTooltip={true}
      >
        {/* 正常配置了 icon，会正常显示 */}
        <Item icon="account">Item 1</Item>
        {/* 未配置 icon，会渲染空白占位 */}
        <Item>Item 2 (no icon)</Item>
        {/* 再次配置 icon，正常显示 */}
        <Item icon="account">Item 3</Item>
        {/* SubNav 同理：未配置 icon 时左侧还是留空 */}
        <SubNav label="SubNav no icon">
          <Item icon="account">Sub 1</Item>
          <Item>Sub 2 (no icon)</Item>
        </SubNav>
      </Nav>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('mountNode'));
